    return argument_tokens, next_token


def get_tokens_until_end(tokens, first_token=None):
    """Get tokens until the matching END keyword, properly handling nested CASE statements."""
    argument_tokens = [first_token] if first_token is not None else []

    next_token = next(tokens, None)
    case_count = 0  # Track nested CASE statements

    while next_token is not None and not (
        lower(next_token) == "end" and case_count <= 0
    ):
        argument_tokens.append(next_token)
        if lower(next_token) == "case":
            case_count += 1
        elif lower(next_token) == "end":
            case_count -= 1
        next_token = next(tokens, None)

    return argument_tokens, next_token

